private func acceptInvite(roomID: String) async {
    defer {
        userIndicatorController.retractIndicatorWithId(roomID)
    }

    // Show loading indicator
    userIndicatorController.submitIndicator(
        UserIndicator(id: roomID, type: .modal, title: L10n.commonLoading, persistent: true)
    )

    // Get the invited room proxy
    guard case let .invited(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomID) else {
        displayError()
        return
    }

    // Call client SDK to join the room
    switch await userSession.clientProxy.joinRoom(roomID, via: []) {
    case .success:
        await finishAcceptInvite(roomProxy: roomProxy)
    case .failure(let error):
        switch error {
        case .invalidInvite:
            displayError(title: L10n.dialogTitleError, message: L10n.errorInvalidInvite)
        default:
            displayError()
        }
    }
}
```

**Key steps**:
1. Shows a loading modal indicator
2. Retrieves the invited room proxy from the client
3. Calls `clientProxy.joinRoom()` on the SDK
4. Handles success/failure and calls `finishAcceptInvite`

